<script setup>
import { computed, ref, watch } from 'vue';
import { Store } from '../../../store';
import { money, businessDate } from '../../../domain/pos.js';
import {
  createPettyCashFund, listPettyCashEntries, listPettyCashFunds,
  postPettyCashEntry, updatePettyCashFund,
} from '../../../services/pettyCash.js';
import Icon from '../../ui/EditionIcon.vue';
import Modal from '../../ui/EditionModal.vue';

const emit = defineEmits(['report-data']);
const funds = ref([]), selectedId = ref(''), entries = ref([]), next = ref(''), busy = ref(false), error = ref('');
const createForm = ref(null), entryForm = ref(null), settingsForm = ref(null);
const currency = computed(() => Store.state.selectedCompany?.preferences?.currency || 'RM');
const selected = computed(() => funds.value.find(fund => fund.id === selectedId.value) || null);
const ready = computed(() => Store.state.online && !Store.state.fromCache);
const manage = computed(() => Store.can('pettyCashManage'));
const openFund = computed(() => selected.value?.status === 'open');
const low = computed(() => Boolean(selected.value?.lowBalance) || (selected.value && Number(selected.value.balanceSen) <= Number(selected.value.lowBalanceThresholdSen || 0)));
const label = type => ({ opening:'Opening float',opening_balance:'Opening float',replenishment:'Replenishment',adjustment_in:'Adjustment in',adjustment_out:'Adjustment out',expense:'Expense payment',expense_disbursement:'Expense payment',reconciliation:'Cash count',reversal:'Reversal',reopen:'Reopened for correction',close:'Closed' })[type] || String(type || '').replaceAll('_', ' ');
const signed = entry => Number(entry.signedAmountSen ?? (entry.direction === 'out' ? -Math.abs(entry.amountSen) : entry.amountSen)) / 100;
const reversible = entry => manage.value && openFund.value && !['opening','opening_balance','close','reversal','expense','expense_disbursement'].includes(entry.type) && !entries.value.some(candidate => candidate.reversesEntryId === entry.id);

function publish(){emit('report-data',{funds:selected.value?[selected.value]:[],entries:entries.value,scope:'selected_fund',complete:!next.value});}
async function loadEntries(append = false){
  if(!selectedId.value){entries.value=[];next.value='';publish();return;}
  const result=await listPettyCashEntries(Store,selectedId.value,{after:append?next.value:'',limit:500});
  entries.value=append?[...entries.value,...(result.rows||[])]:result.rows||[];next.value=result.next||'';
  if(result.fund){const index=funds.value.findIndex(fund=>fund.id===result.fund.id);if(index>=0)funds.value.splice(index,1,result.fund);}
  publish();
}
async function load(){
  if(!Store.can('pettyCashRead')||!Store.state.selectedCompany?.id||!Store.state.online){funds.value=[];entries.value=[];publish();return;}
  busy.value=true;error.value='';
  try{const result=await listPettyCashFunds(Store);funds.value=result.rows||[];const preferred=funds.value.find(fund=>fund.id===selectedId.value)||funds.value.find(fund=>fund.isDefault)||funds.value.find(fund=>fund.status==='open')||funds.value[0];selectedId.value=preferred?.id||'';await loadEntries();}
  catch(caught){error.value=caught.message||'Petty cash could not be loaded.';}finally{busy.value=false;}
}
function openCreate(){createForm.value={name:'Main petty cash',openingBalance:'',lowBalanceThreshold:0,isDefault:!funds.value.length,reason:'Opening float',idempotencyKey:crypto.randomUUID()};error.value='';}
async function create(){if(busy.value||!manage.value||!ready.value)return;busy.value=true;error.value='';try{const result=await createPettyCashFund(Store,{...createForm.value,currency:currency.value});createForm.value=null;await load();selectedId.value=result.fund.id;await loadEntries();Store.notify('Petty cash fund opened.');}catch(caught){error.value=caught.message;}finally{busy.value=false;}}
function openEntry(type, entry = null){entryForm.value=type==='reversal'?{type,reversesEntryId:entry.id,reason:'',occurredAt:businessDate(),idempotencyKey:crypto.randomUUID()}:type==='reconciliation'?{type,countedBalance:'',reason:'Cash count',occurredAt:businessDate(),idempotencyKey:crypto.randomUUID()}:{type,amount:'',reason:'',occurredAt:businessDate(),idempotencyKey:crypto.randomUUID()};error.value='';}
async function postEntry(){if(busy.value||!manage.value||!ready.value||!selected.value)return;busy.value=true;error.value='';try{await postPettyCashEntry(Store,selected.value.id,entryForm.value);entryForm.value=null;await loadEntries();Store.notify('Petty cash ledger updated.');}catch(caught){error.value=caught.message;}finally{busy.value=false;}}
function openSettings(){settingsForm.value={version:selected.value.version,name:selected.value.name,isDefault:selected.value.isDefault,lowBalanceThreshold:Number(selected.value.lowBalanceThresholdSen||0)/100};error.value='';}
async function saveSettings(){if(busy.value||!manage.value||!ready.value||!selected.value)return;busy.value=true;error.value='';try{await updatePettyCashFund(Store,selected.value.id,settingsForm.value);settingsForm.value=null;await load();Store.notify('Petty cash settings saved.');}catch(caught){error.value=caught.message;}finally{busy.value=false;}}
watch(()=>[Store.state.selectedCompany?.id,Store.state.currentUser?.role,Store.state.online],load,{immediate:true});
</script>

<template>
  <section class="petty-panel" aria-labelledby="petty-cash-title">
    <div class="ed-section-head"><div><div class="ed-eyebrow">CONTROL ACCOUNT</div><h2 id="petty-cash-title">Petty cash</h2><p class="ed-muted">Every top-up, payment, count, adjustment, and reversal remains in one auditable ledger.</p></div><div class="ed-actions"><button class="ed-btn" :disabled="busy" @click="load">{{ busy?'Loading…':'Refresh' }}</button><button v-if="manage" class="ed-btn primary" :disabled="!ready" @click="openCreate"><Icon name="plus"/>New fund</button></div></div>
    <div v-if="!ready" class="ed-notice warning">Petty cash is read-only while the live server is unavailable.</div>
    <p v-if="error&&!createForm&&!entryForm&&!settingsForm" class="ed-alert" role="alert">{{ error }}</p>
    <div v-if="funds.length" class="petty-toolbar"><label class="ed-field"><span>Cash fund</span><select v-model="selectedId" @change="loadEntries().catch(caught=>error=caught.message)"><option v-for="fund in funds" :key="fund.id" :value="fund.id">{{ fund.name }} · {{ fund.status }}</option></select></label><button v-if="manage&&selected" class="ed-btn" :disabled="!ready" @click="openSettings"><Icon name="settings"/>Fund settings</button></div>
    <div v-if="selected" class="petty-summary">
      <article><span>Available cash</span><strong>{{ money(selected.balance,currency) }}</strong><small>{{ selected.name }}<template v-if="selected.isDefault"> · default</template></small></article>
      <article><span>Opening float</span><strong>{{ money(Number(selected.openingBalanceSen||0)/100,currency) }}</strong><small>Opened {{ selected.openedAt?new Date(selected.openedAt).toLocaleDateString('en-MY'):'-' }}</small></article>
      <article :class="{warning:low}"><span>Low-balance alert</span><strong>{{ money(Number(selected.lowBalanceThresholdSen||0)/100,currency) }}</strong><small>{{ low?'Replenishment may be needed':'Balance is above threshold' }}</small></article>
      <article><span>Status</span><strong class="petty-status">{{ selected.status }}</strong><small>Ledger version {{ selected.version }}</small></article>
    </div>
    <div v-if="selected&&manage&&openFund" class="petty-actions"><button class="ed-btn" :disabled="!ready" @click="openEntry('replenishment')"><Icon name="plus"/>Replenish</button><button class="ed-btn" :disabled="!ready" @click="openEntry('adjustment_in')">Adjustment in</button><button class="ed-btn" :disabled="!ready" @click="openEntry('adjustment_out')">Adjustment out</button><button class="ed-btn" :disabled="!ready" @click="openEntry('reconciliation')"><Icon name="check"/>Count & reconcile</button><button class="ed-btn" :disabled="!ready||Number(selected.balanceSen)!==0" title="A fund can close only when its balance is zero" @click="openEntry('close')">Close fund</button></div>
    <div v-if="selected" class="ed-table-wrap"><table class="ed-table"><thead><tr><th>Date</th><th>Movement</th><th>Reference / reason</th><th>Recorded by</th><th class="num">Change</th><th class="num">Balance</th><th>Action</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id"><td>{{ new Date(entry.occurredAt||entry.createdAt).toLocaleString('en-MY') }}</td><td><strong>{{ label(entry.type) }}</strong><small v-if="entry.countedBalanceSen!=null">Counted {{ money(entry.countedBalanceSen/100,currency) }}</small></td><td>{{ entry.reference||'—' }}<small>{{ entry.reason||'—' }}</small></td><td>{{ entry.actorName||entry.actorId||'System' }}</td><td class="num" :class="{positive:signed(entry)>0,negative:signed(entry)<0}">{{ signed(entry)>0?'+':'' }}{{ money(signed(entry),currency) }}</td><td class="num">{{ money(Number(entry.balanceAfterSen||0)/100,currency) }}</td><td><button v-if="reversible(entry)" class="ed-btn small" :disabled="!ready" @click="openEntry('reversal',entry)">Reverse</button><span v-else class="ed-muted">—</span></td></tr></tbody></table></div>
    <button v-if="next" class="ed-btn petty-more" :disabled="busy" @click="loadEntries(true)">Load earlier movements</button>
    <div v-if="!funds.length&&!busy" class="ed-empty"><Icon name="wallet"/><h3>No petty cash fund yet.</h3><p>Open a controlled cash float before recording petty cash payments.</p><button v-if="manage" class="ed-btn primary" :disabled="!ready" @click="openCreate">Open first fund</button></div>

    <Modal v-if="createForm" title="Open petty cash fund" :busy="busy" @close="createForm=null"><form id="petty-create" class="ed-form-grid" @submit.prevent="create"><label class="ed-field wide"><span>Fund name</span><input v-model="createForm.name" maxlength="120" required></label><label class="ed-field"><span>Opening float ({{ currency }})</span><input v-model="createForm.openingBalance" type="number" min="0" step="0.01" required></label><label class="ed-field"><span>Low-balance alert ({{ currency }})</span><input v-model="createForm.lowBalanceThreshold" type="number" min="0" step="0.01" required></label><label class="ed-field wide"><span>Reason</span><input v-model="createForm.reason" minlength="3" maxlength="1000" required></label><label class="ed-check wide"><input v-model="createForm.isDefault" type="checkbox"><span>Use as the default petty cash fund</span></label></form><p v-if="error" class="ed-alert">{{ error }}</p><template #actions><button class="ed-btn" :disabled="busy" @click="createForm=null">Cancel</button><button class="ed-btn primary" :disabled="busy||!ready" type="submit" form="petty-create">Open fund</button></template></Modal>
    <Modal v-if="settingsForm" title="Petty cash settings" :busy="busy" @close="settingsForm=null"><form id="petty-settings" class="ed-form-grid" @submit.prevent="saveSettings"><label class="ed-field wide"><span>Fund name</span><input v-model="settingsForm.name" maxlength="120" required></label><label class="ed-field wide"><span>Low-balance alert ({{ currency }})</span><input v-model="settingsForm.lowBalanceThreshold" type="number" min="0" step="0.01" required></label><label class="ed-check wide"><input v-model="settingsForm.isDefault" type="checkbox"><span>Use as the default petty cash fund</span></label></form><p v-if="error" class="ed-alert">{{ error }}</p><template #actions><button class="ed-btn" :disabled="busy" @click="settingsForm=null">Cancel</button><button class="ed-btn primary" :disabled="busy||!ready" type="submit" form="petty-settings">Save settings</button></template></Modal>
    <Modal v-if="entryForm" :title="label(entryForm.type)" :busy="busy" @close="entryForm=null"><form id="petty-entry" class="ed-form-grid" @submit.prevent="postEntry"><label v-if="!['reconciliation','reversal','close'].includes(entryForm.type)" class="ed-field wide"><span>Amount ({{ currency }})</span><input v-model="entryForm.amount" type="number" min="0.01" step="0.01" required></label><label v-if="entryForm.type==='reconciliation'" class="ed-field wide"><span>Cash physically counted ({{ currency }})</span><input v-model="entryForm.countedBalance" type="number" min="0" step="0.01" required></label><label class="ed-field"><span>Effective date</span><input v-model="entryForm.occurredAt" type="date" :max="businessDate()" required></label><label class="ed-field wide"><span>Reason</span><textarea v-model="entryForm.reason" minlength="3" maxlength="1000" required></textarea></label></form><div v-if="entryForm.type==='reconciliation'" class="ed-notice">Expected cash is {{ money(selected.balance,currency) }}. Enter the physical count; any variance will be recorded, not hidden.</div><div v-if="entryForm.type==='reversal'" class="ed-notice warning">The original ledger entry stays visible. This creates a linked reversing entry.</div><p v-if="error" class="ed-alert">{{ error }}</p><template #actions><button class="ed-btn" :disabled="busy" @click="entryForm=null">Cancel</button><button class="ed-btn primary" :disabled="busy||!ready" type="submit" form="petty-entry">Record {{ label(entryForm.type).toLowerCase() }}</button></template></Modal>
  </section>
</template>

<style scoped>
.petty-panel{display:grid;gap:18px}.petty-toolbar{display:flex;align-items:end;gap:12px}.petty-toolbar .ed-field{min-width:min(360px,100%)}.petty-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--ed-line);border-radius:var(--ed-radius);overflow:hidden}.petty-summary article{display:grid;gap:5px;min-height:112px;padding:18px;border-right:1px solid var(--ed-line);background:var(--ed-paper)}.petty-summary article:last-child{border-right:0}.petty-summary article.warning{background:color-mix(in srgb,var(--ed-error) 7%,var(--ed-paper))}.petty-summary span,.petty-summary small{color:var(--ed-muted)}.petty-summary span{font-size:10px;font-weight:650;letter-spacing:.08em;text-transform:uppercase}.petty-summary strong{font-size:22px;font-weight:620}.petty-status{text-transform:capitalize}.petty-actions{display:flex;gap:8px;flex-wrap:wrap}.petty-more{justify-self:center}.num.positive{color:var(--ed-success,#16734b)}.num.negative{color:var(--ed-error,#a53a2c)}@media(max-width:980px){.petty-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.petty-summary article:nth-child(2){border-right:0}.petty-summary article:nth-child(-n+2){border-bottom:1px solid var(--ed-line)}}@media(max-width:600px){.petty-summary{grid-template-columns:1fr}.petty-summary article{border-right:0;border-bottom:1px solid var(--ed-line)}.petty-toolbar{align-items:stretch;flex-direction:column}}
</style>
